#pragma once
// Win/draw/loss display (UCI_ShowWDL).
//
// A reported score v (internal centipawns, side to move) is turned into per-mille chances with a
// logistic model whose centre and width depend on the material on the board:
//
//     W = 1 / (1 + exp((a - v) / b))      L = 1 / (1 + exp((a + v) / b))      D = 1 - W - L
//
// a is the score at which a win becomes as likely as not, b how quickly the result sharpens around it;
// both are cubics in x = clamp(material, lo, hi) / 58, material = P + 3N + 3B + 5R + 9Q over both sides.
// The coefficients (src/wdl_model.hpp) are generated by train/fit_wdl.py from the engine's own
// self-play and belong to the shipped network; another EvalFile is not calibrated by them.
//
// Display only: nothing here feeds the search. The reported cp is the raw internal score unless the
// model was emitted with kNormalizeCp (normalized_cp below: 100 cp = a 50% win chance at the root's
// material); the win/draw/loss shares are always computed from the raw score.
// Mates, tablebase results and 50-move-downgraded mates are decisive (1000 0 0 / 0 0 1000).
#include <algorithm>
#include <cmath>

#include "types.hpp"
#include "wdl_model.hpp"

namespace engine {

struct WdlPermille {
    int win, draw, loss;   // side to move, per mille, sum 1000
};

// Lowest decisive magnitude: every mate and tablebase score, and the 50-move-downgraded value
// VALUE_TB_WIN_IN_MAX_PLY - 1, lies above it (with a MAX_PLY margin below the TB band).
inline constexpr Value kWdlDecisive = VALUE_TB_WIN_IN_MAX_PLY - MAX_PLY;

// P1 N3 B3 R5 Q9 over both sides, kings excluded.
[[nodiscard]] inline int wdl_material(const Board& b) noexcept {
    return b.pieces(PieceType::PAWN).count() + 3 * b.pieces(PieceType::KNIGHT).count() +
           3 * b.pieces(PieceType::BISHOP).count() + 5 * b.pieces(PieceType::ROOK).count() +
           9 * b.pieces(PieceType::QUEEN).count();
}

namespace wdl_detail {
constexpr double horner(const double (&c)[4], double x) noexcept { return ((c[0] * x + c[1]) * x + c[2]) * x + c[3]; }
constexpr double x_of(int material) noexcept {
    return std::clamp(material, wdl_model::kMaterialLo, wdl_model::kMaterialHi) / wdl_model::kMaterialAnchor;
}
// a > 0 and b > 0 keep D >= 0 (W + L <= 1 exactly when a / b >= 0).
constexpr bool model_positive() noexcept {
    for (int m = wdl_model::kMaterialLo; m <= wdl_model::kMaterialHi; ++m)
        if (!(horner(wdl_model::kA, x_of(m)) > 0.0 && horner(wdl_model::kB, x_of(m)) > 0.0)) return false;
    return true;
}
}  // namespace wdl_detail

static_assert(wdl_detail::model_positive(), "wdl_model.hpp: a(m) and b(m) must be positive on the clamp range");

[[nodiscard]] constexpr WdlPermille wdl_from_value(Value v, int material) noexcept {
    if (v >= kWdlDecisive) return {1000, 0, 0};
    if (v <= -kWdlDecisive) return {0, 0, 1000};
    const double x = wdl_detail::x_of(material);
    const double a = wdl_detail::horner(wdl_model::kA, x);
    const double b = wdl_detail::horner(wdl_model::kB, x);
    int w = static_cast<int>(0.5 + 1000.0 / (1.0 + std::exp((a - v) / b)));
    int l = static_cast<int>(0.5 + 1000.0 / (1.0 + std::exp((a + v) / b)));
    if (w + l > 1000) {   // per-mille rounding can overshoot by one: keep D >= 0
        if (w >= l) w = 1000 - l;
        else l = 1000 - w;
    }
    return {w, 1000 - w - l, l};
}

// Reported cp, normalized: v * 100 / a(material), a being the score the model gives a 50% win chance,
// so a reported 100 is a 50% win at the root's material. Rounded half away from zero; decisive scores
// (the tablebase band; mates print as mate) pass through. -DSC_CP_NORM=0/1 overrides the model's flag.
#ifdef SC_CP_NORM
inline constexpr bool kCpNorm = SC_CP_NORM != 0;
#else
inline constexpr bool kCpNorm = wdl_model::kNormalizeCp;
#endif

[[nodiscard]] constexpr int normalized_cp(Value v, int material) noexcept {
    if (v >= kWdlDecisive || v <= -kWdlDecisive) return v;
    const double q = 100.0 * v / wdl_detail::horner(wdl_model::kA, wdl_detail::x_of(material));
    return static_cast<int>(q < 0 ? q - 0.5 : q + 0.5);
}

namespace wdl_detail {
// The definition holds on the whole clamp range: the internal score nearest a(m) reports exactly 100
// (when a >= 100, an internal cp moves the report by at most one).
constexpr bool normalization_anchored() noexcept {
    for (int m = wdl_model::kMaterialLo; m <= wdl_model::kMaterialHi; ++m) {
        const double a = horner(wdl_model::kA, x_of(m));
        if (a < 100.0) continue;
        const Value va = static_cast<Value>(a + 0.5);
        if (normalized_cp(va, m) != 100 || normalized_cp(-va, m) != -100) return false;
    }
    return true;
}
}  // namespace wdl_detail

static_assert(wdl_detail::normalization_anchored(), "wdl_model.hpp: a(m) must report as 100 cp");
static_assert(normalized_cp(VALUE_TB_WIN_IN_MAX_PLY - 1, 40) == VALUE_TB_WIN_IN_MAX_PLY - 1);
static_assert(normalized_cp(0, 40) == 0);

static_assert(wdl_from_value(VALUE_MATE - 1, 40).win == 1000 && wdl_from_value(-(VALUE_MATE - 1), 40).loss == 1000);
static_assert(wdl_from_value(kWdlDecisive, 0).win == 1000 && wdl_from_value(-kWdlDecisive, 90).loss == 1000);
static_assert(wdl_from_value(VALUE_TB_WIN_IN_MAX_PLY - 1, 78).win == 1000);   // a 50-move-downgraded mate

}  // namespace engine
